#!/usr/bin/env bash
# Question 2: Unhealthy worker. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

case "${Q2_FAULT}" in
  kubelet-stopped)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q2_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && exit 0
      sleep 2
    done
    echo "the node is still Ready" >&2
    exit 1
    ;;
  containerd-stopped)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q2_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && exit 0
      sleep 2
    done
    echo "the node is still Ready" >&2
    exit 1
    ;;
  kubelet-binary-path)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q2_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" != True ]] && exit 0
      sleep 2
    done
    echo "the node is still Ready" >&2
    exit 1
    ;;
  cordoned) ;;
  stray-taint) ;;
esac
